/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import readline from 'readline'

// ============================================================================
// Main entry point
// ============================================================================

async function main() {
  try {
    const args = process.argv.slice(2)

    // Parse command line arguments
    if (args.length === 0) {
      process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
      process.exit(2)
    }

    const mode = args[0]

    if (mode !== 'waves' && mode !== 'explain' && mode !== 'pack') {
      process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
      process.exit(2)
    }

    if (mode === 'pack') {
      if (args.length !== 2) {
        process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
        process.exit(2)
      }

      const workers = args[1]
      if (!/^\d+$/.test(workers) || workers === '0' || workers[0] === '0') {
        process.stderr.write('error: workers must be a positive integer\n')
        process.exit(2)
      }
    }

    // Read input
    const lines = await readInput()

    // Parse the build graph
    const { tasks, deps, lineErrors } = parseInput(lines)

    // Check for parse errors
    if (lineErrors.length > 0) {
      process.stderr.write(lineErrors[0] + '\n')
      process.exit(2)
    }

    // Check for unknown task references
    for (const [name, depList] of Object.entries(deps)) {
      if (!(name in tasks)) {
        // This shouldn't happen since we validate in parseInput
      }
      for (const dep of depList) {
        if (!(dep in tasks)) {
          process.stderr.write(`error: unknown task ${dep}\n`)
          process.exit(2)
        }
      }
    }

    // Build the graph
    const graph = buildGraph(tasks, deps)

    // Detect cycles
    const cycle = detectCycle(graph)
    if (cycle) {
      const cycleStr = cycle.join(' -> ')
      process.stderr.write(`error: cycle: ${cycleStr} -> ${cycle[0]}\n`)
      process.exit(3)
    }

    // Execute the mode
    if (mode === 'waves') {
      executeWaves(graph, tasks)
    } else if (mode === 'explain') {
      executeExplain(graph, tasks)
    } else if (mode === 'pack') {
      const workerCount = parseInt(args[1])
      executePack(graph, tasks, workerCount)
    }
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
}

// ============================================================================
// Input reading
// ============================================================================

async function readInput() {
  return new Promise((resolve) => {
    let input = ''
    const rl = readline.createInterface({
      input: process.stdin,
      output: null,
      terminal: false
    })

    rl.on('line', (line) => {
      input += line + '\n'
    })

    rl.on('close', () => {
      resolve(input)
    })
  })
}

// ============================================================================
// Input parsing
// ============================================================================

function parseInput(input) {
  const tasks = {}
  const deps = {}
  const lineErrors = []

  let lineNum = 0
  const lines = input.split('\n')

  for (const rawLine of lines) {
    lineNum++

    // Trim and ignore empty lines and comments
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }

    // Split on whitespace
    const words = line.split(/\s+/)
    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        lineErrors.push(`error: line ${lineNum}: expected task <name> <cost>`)
        continue
      }

      const name = words[1]
      const costStr = words[2]

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        lineErrors.push(`error: line ${lineNum}: invalid task name ${name}`)
        continue
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        lineErrors.push(`error: line ${lineNum}: cost must be a non-negative integer`)
        continue
      }

      // Check for leading zeros (except for "0" itself)
      if (costStr.length > 1 && costStr[0] === '0') {
        lineErrors.push(`error: line ${lineNum}: cost must be a non-negative integer`)
        continue
      }

      // Check for duplicate task
      if (name in tasks) {
        lineErrors.push(`error: line ${lineNum}: task ${name} is declared twice`)
        continue
      }

      const cost = parseInt(costStr)
      tasks[name] = cost
      if (!(name in deps)) {
        deps[name] = []
      }
    } else if (directive === 'dep') {
      if (words.length < 2) {
        lineErrors.push(`error: line ${lineNum}: expected dep <name> <dependency>...`)
        continue
      }

      const name = words[0]
      const depList = words.slice(1)

      // Initialize deps entry if not present
      if (!(name in deps)) {
        deps[name] = []
      }

      // Add dependencies (avoid duplicates)
      for (const dep of depList) {
        if (!deps[name].includes(dep)) {
          deps[name].push(dep)
        }
      }
    } else {
      lineErrors.push(`error: line ${lineNum}: unknown directive ${directive}`)
      continue
    }
  }

  return { tasks, deps, lineErrors }
}

// ============================================================================
// Graph building
// ============================================================================

function buildGraph(tasks, deps) {
  const graph = {}

  for (const name in tasks) {
    graph[name] = {
      cost: tasks[name],
      dependencies: deps[name] || [],
      dependents: []
    }
  }

  // Build reverse dependencies
  for (const name in graph) {
    for (const dep of graph[name].dependencies) {
      if (!(dep in graph.dependents)) {
        graph[dep].dependents = graph[dep].dependents || []
      }
      graph[dep].dependents.push(name)
    }
  }

  return graph
}

// ============================================================================
// Cycle detection using DFS
// ============================================================================

function detectCycle(graph) {
  const taskNames = Object.keys(graph).sort()

  for (const startName of taskNames) {
    const visited = new Set()
    const recStack = []

    const dfs = (name) => {
      if (visited.has(name)) {
        // Check if it's in the recursion stack
        const idx = recStack.indexOf(name)
        if (idx >= 0) {
          // Cycle found
          return recStack.slice(idx)
        }
        return null
      }

      visited.add(name)
      recStack.push(name)

      // Visit dependencies in ascending order
      const deps = graph[name].dependencies.sort()
      for (const dep of deps) {
        const cycle = dfs(dep)
        if (cycle) {
          return cycle
        }
      }

      recStack.pop()
      return null
    }

    const cycle = dfs(startName)
    if (cycle) {
      return cycle
    }
  }

  return null
}

// ============================================================================
// Wave calculation
// ============================================================================

function calculateWaves(graph) {
  const waves = {}
  const depth = {}

  // Calculate depth for each task
  const calculateDepth = (name, memo = {}) => {
    if (name in memo) return memo[name]

    const node = graph[name]
    if (node.dependencies.length === 0) {
      memo[name] = 0
      return 0
    }

    let maxDepth = 0
    for (const dep of node.dependencies) {
      maxDepth = Math.max(maxDepth, calculateDepth(dep, memo))
    }

    memo[name] = maxDepth + 1
    return maxDepth + 1
  }

  // Calculate depth for all tasks
  for (const name in graph) {
    depth[name] = calculateDepth(name)
  }

  // Group by wave
  for (const name in depth) {
    const w = depth[name]
    if (!(w in waves)) {
      waves[w] = []
    }
    waves[w].push(name)
  }

  // Sort task names within each wave
  for (const w in waves) {
    waves[w].sort()
  }

  return { waves, depth }
}

// ============================================================================
// Task scheduling
// ============================================================================

function calculateSchedule(graph) {
  const schedule = {}

  const calculate = (name, memo = {}) => {
    if (name in memo) return memo[name]

    const node = graph[name]
    let startTime = 0

    for (const dep of node.dependencies) {
      const depSchedule = calculate(dep, memo)
      startTime = Math.max(startTime, depSchedule.finish)
    }

    const finish = startTime + node.cost

    memo[name] = { start: startTime, finish }
    return memo[name]
  }

  for (const name in graph) {
    schedule[name] = calculate(name)
  }

  return schedule
}

// ============================================================================
// Execution modes
// ============================================================================

function executeWaves(graph, tasks) {
  const { waves, depth } = calculateWaves(graph)

  // Print waves
  const waveNums = Object.keys(waves).map(Number).sort((a, b) => a - b)
  for (const w of waveNums) {
    const taskNames = waves[w].sort()
    process.stdout.write(`wave ${w}: ${taskNames.join(' ')}\n`)
  }

  // Calculate makespan
  const schedule = calculateSchedule(graph)
  let makespan = 0
  for (const name in schedule) {
    makespan = Math.max(makespan, schedule[name].finish)
  }

  process.stdout.write(`total ${makespan}\n`)
}

function executeExplain(graph, tasks) {
  const { depth } = calculateWaves(graph)
  const schedule = calculateSchedule(graph)

  // Print tasks in ascending order
  const taskNames = Object.keys(graph).sort()
  for (const name of taskNames) {
    const s = schedule[name].start
    const f = schedule[name].finish
    const d = depth[name]
    process.stdout.write(`${name} start=${s} finish=${f} depth=${d}\n`)
  }

  // Calculate and print makespan
  let makespan = 0
  for (const name in schedule) {
    makespan = Math.max(makespan, schedule[name].finish)
  }

  process.stdout.write(`total ${makespan}\n`)
}

function executePack(graph, tasks, workerCount) {
  // Calculate priority for each task (longest chain starting at it)
  const priority = {}

  const calculatePriority = (name, memo = {}) => {
    if (name in memo) return memo[name]

    const node = graph[name]
    let maxChain = 0

    // Check all dependents
    for (const dependent of node.dependents || []) {
      maxChain = Math.max(maxChain, calculatePriority(dependent, memo))
    }

    const result = node.cost + maxChain
    memo[name] = result
    return result
  }

  for (const name in graph) {
    priority[name] = calculatePriority(name)
  }

  // Simulate scheduling
  const workers = Array.from({ length: workerCount }, () => ({
    free: 0,
    tasks: []
  }))

  const finished = {}
  let currentTime = 0

  while (Object.keys(finished).length < Object.keys(graph).length) {
    // Find all ready tasks
    const ready = []

    for (const name in graph) {
      if (name in finished) continue

      const node = graph[name]
      let canStart = true

      for (const dep of node.dependencies) {
        if (!(dep in finished)) {
          canStart = false
          break
        }
      }

      if (canStart) {
        ready.push(name)
      }
    }

    // Find next time when a worker is free
    let nextFreeTime = Infinity
    for (const worker of workers) {
      if (worker.free <= currentTime) {
        nextFreeTime = currentTime
        break
      }
      nextFreeTime = Math.min(nextFreeTime, worker.free)
    }

    currentTime = nextFreeTime

    // Assign ready tasks to free workers
    let assigned = true
    while (assigned && ready.length > 0) {
      assigned = false

      // Find free worker with smallest index
      let freeWorkerIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].free <= currentTime) {
          freeWorkerIdx = i
          break
        }
      }

      if (freeWorkerIdx === -1) break

      // Find ready task with greatest priority, break ties by ascending name
      let bestTask = null
      let bestPriority = -1

      for (const task of ready) {
        if (priority[task] > bestPriority || 
            (priority[task] === bestPriority && (!bestTask || task < bestTask))) {
          bestTask = task
          bestPriority = priority[task]
        }
      }

      if (bestTask) {
        // Assign task to worker
        const node = graph[bestTask]
        const start = Math.max(currentTime, ...node.dependencies.map(dep => finished[dep].finish || 0))
        const finish = start + node.cost

        workers[freeWorkerIdx].tasks.push({
          name: bestTask,
          start,
          finish
        })

        workers[freeWorkerIdx].free = finish
        finished[bestTask] = { finish }

        // Remove from ready
        ready.splice(ready.indexOf(bestTask), 1)
        assigned = true
      }
    }

    // Check if we're done
    if (Object.keys(finished).length === Object.keys(graph).length) break
  }

  // Output results
  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const worker = workers[i]
    let line = `worker ${i}:`

    for (const task of worker.tasks) {
      line += ` ${task.name}@${task.start}-${task.finish}`
      makespan = Math.max(makespan, task.finish)
    }

    process.stdout.write(line + '\n')
  }

  process.stdout.write(`makespan ${makespan}\n`)
}

// ============================================================================
// Entry point
// ============================================================================

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
"}

