    free: 0,
    tasks: []
  }))

  const finished = {}
  let currentTime = 0

  while (Object.keys(finished).length < Object.keys(graph).length) {
    // Find all ready tasks
    const ready = []

    for (const name in graph) {
      if (name in finished) continue

      const node = graph[name]
      let canStart = true

      for (const dep of node.dependencies) {
        if (!(dep in finished)) {
          canStart = false
          break
        }
      }

      if (canStart) {
        ready.push(name)
      }
    }

    // Find next time when a worker is free
    let nextFreeTime = Infinity
    for (const worker of workers) {
      if (worker.free <= currentTime) {
        nextFreeTime = currentTime
        break
      }
      nextFreeTime = Math.min(nextFreeTime, worker.free)
    }

    currentTime = nextFreeTime

    // Assign ready tasks to free workers
    let assigned = true
    while (assigned && ready.length > 0) {
      assigned = false

      // Find free worker with smallest index
      let freeWorkerIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].free <= currentTime) {
          freeWorkerIdx = i
          break
        }
      }

