        if (priority[task] > bestPriority || 
            (priority[task] === bestPriority && (!bestTask || task < bestTask))) {
          bestTask = task
          bestPriority = priority[task]
        }
      }

      if (bestTask) {
        // Assign task to worker
        const node = graph[bestTask]
        const start = Math.max(currentTime, ...node.dependencies.map(dep => finished[dep].finish || 0))
        const finish = start + node.cost

        workers[freeWorkerIdx].tasks.push({
          name: bestTask,
          start,
          finish
        })

        workers[freeWorkerIdx].free = finish
        finished[bestTask] = { finish }

        // Remove from ready
        ready.splice(ready.indexOf(bestTask), 1)
        assigned = true
      }
    }

    // Check if we're done
    if (Object.keys(finished).length === Object.keys(graph).length) break
  }

  // Output results
  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const worker = workers[i]
    let line = `worker ${i}:`

    for (const task of worker.tasks) {
      line += ` ${task.name}@${task.start}-${task.finish}`
      makespan = Math.max(makespan, task.finish)
    }

    process.stdout.write(line + '\n')
  }

  process.stdout.write(`makespan ${makespan}\n`)
}

// ============================================================================
// Entry point
// ============================================================================

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
"}

