  for (const name in graph) {
    for (const dep of graph[name].dependencies) {
      if (!(dep in graph.dependents)) {
        graph[dep].dependents = graph[dep].dependents || []
      }
      graph[dep].dependents.push(name)
    }
  }

  return graph
}

// ============================================================================
// Cycle detection using DFS
// ============================================================================

function detectCycle(graph) {
  const taskNames = Object.keys(graph).sort()

  for (const startName of taskNames) {
    const visited = new Set()
    const recStack = []

    const dfs = (name) => {
      if (visited.has(name)) {
        // Check if it's in the recursion stack
        const idx = recStack.indexOf(name)
        if (idx >= 0) {
          // Cycle found
          return recStack.slice(idx)
        }
        return null
      }

